import { useEffect, useState } from 'react'
import QRCode from 'qrcode'
import { Link, useLocation, useNavigate } from 'react-router-dom'
import { supabase } from '../lib/supabase'

import { menuImageBucket, restaurantSlug, scanLink } from '../lib/restaurant-config'
import { describeAuthError } from '../lib/auth-errors'
import { useTheme } from '../lib/theme'
import BrandMark from './BrandMark'
import './Admin.css'
// Imported after Admin.css so the dark layer is the later of the two for equal
// specificity. Every rule in it is also more specific than what it overrides.
import './AdminTheme.css'

const nav = [['dashboard', '⌂', 'Overview'], ['menu', '◫', 'Menu'], ['offers', '✦', 'Offers'], ['categories', '☷', 'Categories'], ['qr', '▦', 'QR Codes'], ['subscription', '▣', 'Subscription'], ['usage', '▥', 'Usage'], ['settings', '⚙', 'Settings']]
const subscriptionPages = ['subscription', 'payment', 'billing', 'notifications']
const Field = ({ label, children }) => <label>{label}{children}</label>
const PageLoader = ({ label = 'Loading data' }) => <div className="page-loader"><div className="loader-orbit"><i /><i /><i /></div><strong>{label}</strong><span>Please wait a moment</span></div>
const notify = (message, tone = 'success') => window.dispatchEvent(new CustomEvent('admin-feedback', { detail: { message, tone } }))
function Feedback() { const [notice, setNotice] = useState(null); useEffect(() => { const show = (event) => { setNotice(event.detail); window.setTimeout(() => setNotice(null), 3200) }; window.addEventListener('admin-feedback', show); return () => window.removeEventListener('admin-feedback', show) }, []); return notice && <div className={`admin-toast ${notice.tone}`} role="status">{notice.tone === 'success' ? '✓' : '!' } <span>{notice.message}</span></div> }

const loginLockKey = `palatotable-admin-lock:${restaurantSlug}`
const getLoginLock = () => { try { const value = JSON.parse(localStorage.getItem(loginLockKey) || 'null'); return value?.lockedUntil > Date.now() ? value : null } catch { return null } }

function Login() {
  const navigate = useNavigate(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); const [lock, setLock] = useState(getLoginLock); const [now, setNow] = useState(() => Date.now()); const [tenant, setTenant] = useState(() => (supabase && restaurantSlug ? undefined : null))
  useEffect(() => { const timer = window.setInterval(() => { setNow(Date.now()); const activeLock = getLoginLock(); setLock(activeLock); if (!activeLock) localStorage.removeItem(loginLockKey) }, 1000); return () => window.clearInterval(timer) }, [])
  // The sign-in screen names the restaurant it belongs to, and a slug with no
  // restaurant is reported here instead of showing a form that can never work.
  useEffect(() => { let active = true; if (!supabase || !restaurantSlug) return undefined; supabase.rpc('public_tenant_by_slug', { p_slug: restaurantSlug }).then(({ data, error: lookupError }) => { if (!active) return; const record = Array.isArray(data) ? data[0] : data; setTenant(lookupError ? null : record || null) }); return () => { active = false } }, [])
  const submit = async (e) => { e.preventDefault(); const activeLock = getLoginLock(); if (activeLock) { setLock(activeLock); return } if (!supabase) return setError('Add Supabase environment variables first.'); setLoading(true); const { error: authError } = await supabase.auth.signInWithPassword({ email: email.trim().toLowerCase(), password }); if (authError) { const described = describeAuthError(authError); if (!described.isCredentialFailure) { setError(described.message); setLoading(false); return } const previous = (() => { try { return JSON.parse(localStorage.getItem(loginLockKey) || 'null') } catch { return null } })(); const attempts = (previous?.attempts || 0) + 1; if (attempts >= 3) { const nextLock = { attempts, lockedUntil: Date.now() + 60 * 60 * 1000 }; localStorage.setItem(loginLockKey, JSON.stringify(nextLock)); setLock(nextLock); setError('This device is locked for one hour after three failed attempts.') } else { localStorage.setItem(loginLockKey, JSON.stringify({ attempts })); setError(`${described.message} ${3 - attempts} attempt${3 - attempts === 1 ? '' : 's'} remaining.`) } setPassword(''); setLoading(false) } else { localStorage.removeItem(loginLockKey); navigate(`/admin/${restaurantSlug}`) } }
  const secondsLeft = lock ? Math.max(0, Math.ceil((lock.lockedUntil - now) / 1000)) : 0; const lockTime = `${String(Math.floor(secondsLeft / 60)).padStart(2, '0')}:${String(secondsLeft % 60).padStart(2, '0')}`
  if (tenant === null) return <main className="scan-error"><BrandMark size={42} /><h1>Restaurant not found</h1><p>No restaurant is registered at <strong>/{restaurantSlug}</strong>. Check the address, or ask the platform team for the correct link.</p><Link className="admin-primary" to="/">Back to platform home</Link></main>
  return <main className="login-page"><section className="login-visual"><Link className="login-brand" to={`/${restaurantSlug}`}><BrandMark size={37} />Plato Table</Link><div><span className="login-kicker">RESTAURANT COMMAND CENTER</span><h1>Your menu.<br /><em>Managed simply.</em></h1><p>A focused workspace for your menu, table QR codes, and restaurant details.</p></div></section><section className="login-form-wrap"><form className="login-form" onSubmit={submit} autoComplete="off"><div className="login-mobile-brand"><BrandMark size={38} /><strong>Plato Table</strong></div><span className="eyebrow">STAFF PORTAL</span><h2>{lock ? 'Access paused' : 'Welcome back'}</h2><p>{lock ? `Try again when the device lock ends in ${lockTime}.` : (tenant?.name ? `Sign in to manage ${tenant.name}.` : 'Sign in to manage your restaurant workspace.')}</p><Field label="Admin email"><input required type="email" name="staff-email" autoComplete="email" placeholder="owner@yourrestaurant.com" value={email} onChange={(e) => setEmail(e.target.value)} /></Field><Field label="Password"><input required disabled={Boolean(lock)} type="password" name="staff-password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field>{(error || lock) && <div className="login-error">{lock ? `Too many failed attempts. This device is locked for ${lockTime}.` : error}</div>}<button className="admin-primary login-submit" disabled={loading || Boolean(lock)}>{loading ? 'Signing in…' : lock ? `Try again in ${lockTime}` : 'Sign in securely'}</button><small>Three incorrect passwords lock this browser for one hour.</small></form></section></main>
}

function useData(table, restaurantId, order = 'display_order') {
  const [data, setData] = useState([]); const [error, setError] = useState(''); const [loading, setLoading] = useState(true)
  const reload = async () => { if (!restaurantId) return; setLoading(true); const result = await supabase.from(table).select('*').eq('restaurant_id', restaurantId).order(order, { ascending: order === 'display_order' }); if (result.error) setError(result.error.message); else setData(result.data || []); setLoading(false) }
  useEffect(() => { if (!restaurantId) return; supabase.from(table).select('*').eq('restaurant_id', restaurantId).order(order, { ascending: order === 'display_order' }).then((result) => { if (result.error) setError(result.error.message); else setData(result.data || []); setLoading(false) }) }, [restaurantId, table, order])
  return { data, error, loading, reload }
}

function Dashboard({ restaurantId, openPage }) {
  const { data: menu, loading: menuLoading } = useData('menu_items', restaurantId); const { data: categories, loading: categoryLoading } = useData('categories', restaurantId); const { data: tables, loading: tableLoading } = useData('qr_tokens', restaurantId, 'created_at')
  if (menuLoading || categoryLoading || tableLoading) return <PageLoader label="Loading dashboard" />
  const stats = [['Tables', tables.length, '▦', 'qr'], ['Menu items', menu.length, '◫', 'menu'], ['Categories', categories.length, '☷', 'categories']]
  return <><Header kicker="DAYNIGHT WORKSPACE" title="Good to see you" /><section className="admin-welcome"><div><span>YOUR RESTAURANT IS READY</span><strong>Keep your menu accurate and your table QR codes ready for guests.</strong></div><button onClick={() => openPage('qr')}>Manage table QRs <span>→</span></button></section><div className="stats-grid">{stats.map(([label, value, icon, page]) => <button className="stat-card" key={label} onClick={() => openPage(page)}><div className="stat-icon">{icon}</div><span>{label}</span><strong>{value}</strong><small>Manage {label.toLowerCase()} →</small></button>)}</div><section className="quick-actions"><div><span className="admin-kicker">QUICK ACTIONS</span><h2>What do you need to do?</h2></div><button onClick={() => openPage('menu')}><b>＋</b><span><strong>Add a food item</strong><small>Add a dish, price, photo and category</small></span></button><button onClick={() => openPage('categories')}><b>☷</b><span><strong>Organize categories</strong><small>Keep your digital menu easy to browse</small></span></button></section></>
}

function Categories({ restaurantId }) {
  const { data, error, loading, reload } = useData('categories', restaurantId); const { data: menuItems, loading: menuLoading } = useData('menu_items', restaurantId); const [editing, setEditing] = useState(null); const save = async (e) => { e.preventDefault(); const f = new FormData(e.currentTarget); const record = { restaurant_id: restaurantId, name: f.get('name').trim(), display_order: editing?.display_order ?? data.length, is_active: true }; const result = editing?.id ? await supabase.from('categories').update(record).eq('id', editing.id) : await supabase.from('categories').insert(record); if (result.error) return alert(result.error.message); setEditing(null); reload() }
  const remove = async (row) => { if (confirm(`Delete ${row.name}?`)) { const { error: deleteError } = await supabase.from('categories').delete().eq('id', row.id); if (deleteError) alert(deleteError.message); else reload() } }
  if (loading || menuLoading) return <PageLoader label="Loading categories" />
    return <><Header kicker={`${data.length} CATEGORIES`} title="Category management" action="Add category" onAction={() => setEditing({ name: '' })} />{error && <div className="login-error">{error}</div>}<div className="category-admin-list">{data.map((row) => <article className="category-admin-row" key={row.id}><div><strong>{row.name}</strong><small>{menuItems.filter((item) => item.category_id === row.id).length} item(s)</small></div><div><button className="admin-secondary" onClick={() => setEditing(row)}>Edit</button><button className="danger-button" onClick={() => remove(row)}>Delete</button></div></article>)}</div>{editing && <Modal title={editing.id ? 'Edit category' : 'Add category'} close={() => setEditing(null)}><form onSubmit={save} className="admin-form-grid"><Field label="Category name"><input name="name" required defaultValue={editing.name} placeholder="e.g. Burgers" /></Field><button className="admin-primary">Save category</button></form></Modal>}</>
}

function MenuItemForm({ editing, categories, onSave }) {
  const initialImages = editing?.image_urls?.length ? editing.image_urls : editing?.image_url ? [editing.image_url] : []
  const [images, setImages] = useState(() => initialImages.map((url) => ({ id: crypto.randomUUID(), type: 'url', url, preview: url })))
  const [imageLink, setImageLink] = useState('')
  const addFiles = (event) => { const files = Array.from(event.target.files || []); const tooLarge = files.find((file) => file.size > 5242880); if (tooLarge) return notify('Each image must be 5 MB or smaller.', 'error'); setImages((current) => [...current, ...files.map((file) => ({ id: crypto.randomUUID(), type: 'file', file, preview: URL.createObjectURL(file) }))]); event.target.value = '' }
  const addLink = () => { const url = imageLink.trim(); if (!url) return; try { new URL(url) } catch { notify('Enter a complete public image URL.', 'error'); return } setImages((current) => [...current, { id: crypto.randomUUID(), type: 'url', url, preview: url }]); setImageLink('') }
  return <form onSubmit={(event) => { event.preventDefault(); onSave(new FormData(event.currentTarget), images) }} className="admin-form-grid"><Field label="Item name"><input name="name" required defaultValue={editing.name || ''} /></Field><Field label="Category"><select name="category" defaultValue={editing.category_id || ''}><option value="">No category</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><Field label="Price"><input name="price" type="number" min="0" required defaultValue={editing.price || ''} /></Field><Field label="Available"><input name="available" type="checkbox" defaultChecked={editing.is_available ?? true} /></Field><Field label="Description"><textarea name="description" defaultValue={editing.description || ''} placeholder="Describe this dish" /></Field><section className="image-manager"><div className="image-manager-head"><div><strong>Product images</strong><small>Add photos from your device or public image links.</small></div><span>{images.length} image{images.length === 1 ? '' : 's'}</span></div><div className="image-actions"><label className="image-upload-button">↑ Upload images<input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif" onChange={addFiles} /></label><div className="image-link-add"><input value={imageLink} onChange={(event) => setImageLink(event.target.value)} placeholder="Paste image URL" /><button type="button" onClick={addLink}>Add link</button></div></div>{images.length > 0 && <div className="image-preview-grid">{images.map((image, index) => <article key={image.id}><img src={image.preview} alt="" decoding="async" /><span>{index === 0 ? 'Cover image' : `Image ${index + 1}`}</span><button type="button" onClick={() => setImages((current) => current.filter((item) => item.id !== image.id))} aria-label="Remove image">×</button></article>)}</div>}</section><button className="admin-primary">{editing.id ? 'Save changes' : 'Add menu item'}</button></form>
}

function Menu({ restaurantId }) {
  const { data: items, error, loading, reload } = useData('menu_items', restaurantId); const { data: categories, loading: categoriesLoading } = useData('categories', restaurantId); const [editing, setEditing] = useState(null); const [query, setQuery] = useState(''); const [categoryFilter, setCategoryFilter] = useState(''); const [minPrice, setMinPrice] = useState(''); const [maxPrice, setMaxPrice] = useState(''); const [availability, setAvailability] = useState('all'); const [filtersOpen, setFiltersOpen] = useState(false)
  const save = async (formData, images) => { const files = images.filter((image) => image.type === 'file').map((image) => image.file); const linkedImages = images.filter((image) => image.type === 'url').map((image) => image.url); const uploadedImages = []; for (const file of files) { const path = `${restaurantId}/${crypto.randomUUID()}-${file.name.replaceAll(' ', '-')}`; const { error: uploadError } = await supabase.storage.from(menuImageBucket).upload(path, file, { upsert: false }); if (uploadError) return notify(uploadError.message, 'error'); uploadedImages.push(supabase.storage.from(menuImageBucket).getPublicUrl(path).data.publicUrl) } const imageUrls = [...linkedImages, ...uploadedImages]; const record = { restaurant_id: restaurantId, category_id: formData.get('category') || null, name: formData.get('name').trim(), description: formData.get('description').trim() || null, price: Number(formData.get('price')), image_url: imageUrls[0] || null, image_urls: imageUrls, is_available: formData.get('available') === 'on' }; const result = editing?.id ? await supabase.from('menu_items').update(record).eq('id', editing.id) : await supabase.from('menu_items').insert(record); if (result.error) return notify(result.error.message, 'error'); setEditing(null); reload(); notify(editing?.id ? 'Menu item updated.' : 'Menu item added.') }
  const toggle = async (row) => { const { error: updateError } = await supabase.from('menu_items').update({ is_available: !row.is_available }).eq('id', row.id); if (updateError) alert(updateError.message); else reload() }
  const remove = async (row) => { if (confirm(`Delete ${row.name}?`)) { const { error: deleteError } = await supabase.from('menu_items').delete().eq('id', row.id); if (deleteError) alert(deleteError.message); else reload() } }
  const visibleItems = items.filter((row) => (!categoryFilter || row.category_id === categoryFilter) && (!minPrice || Number(row.price) >= Number(minPrice)) && (!maxPrice || Number(row.price) <= Number(maxPrice)) && (availability === 'all' || (availability === 'available' && row.is_available) || (availability === 'sold-out' && !row.is_available)) && `${row.name} ${row.description || ''}`.toLowerCase().includes(query.toLowerCase()))
  const resetFilters = () => { setCategoryFilter(''); setMinPrice(''); setMaxPrice(''); setAvailability('all') }
  if (loading || categoriesLoading) return <PageLoader label="Loading menu" />
  return <><Header kicker={`${items.length} MENU ITEMS`} title="Menu management" action="Add item" onAction={() => setEditing({})} />{error && <div className="login-error">{error}</div>}<div className="content-toolbar"><label className="toolbar-search">⌕<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search food items" /></label><button className="admin-secondary" onClick={() => setFiltersOpen(true)}>☷ Filters</button></div><p className="result-summary">Showing {visibleItems.length} of {items.length} menu items</p>{filtersOpen && <div className="filter-backdrop" onClick={() => setFiltersOpen(false)}><aside className="filter-drawer" onClick={(e) => e.stopPropagation()}><header><div><span className="admin-kicker">MENU FILTERS</span><h2>Refine menu</h2></div><button onClick={() => setFiltersOpen(false)}>×</button></header><Field label="Category"><select value={categoryFilter} onChange={(e) => setCategoryFilter(e.target.value)}><option value="">All categories</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><div className="price-range"><Field label="Minimum price"><input value={minPrice} onChange={(e) => setMinPrice(e.target.value)} type="number" min="0" placeholder="0" /></Field><Field label="Maximum price"><input value={maxPrice} onChange={(e) => setMaxPrice(e.target.value)} type="number" min="0" placeholder="No limit" /></Field></div><Field label="Availability"><select value={availability} onChange={(e) => setAvailability(e.target.value)}><option value="all">All items</option><option value="available">Available</option><option value="sold-out">Sold out</option></select></Field><footer><button className="admin-secondary" onClick={resetFilters}>Reset</button><button className="admin-primary" onClick={() => setFiltersOpen(false)}>Apply filters</button></footer></aside></div>}<div className="admin-menu-grid">{visibleItems.map((row) => <article className={`admin-dish ${row.is_available ? '' : 'unavailable'}`} key={row.id}>{row.image_url && <img src={row.image_url} alt="" loading="lazy" decoding="async" />}<div><h3>{row.name}</h3><p>{row.description}</p><footer><strong>PKR {Number(row.price).toLocaleString()}</strong><button className={row.is_available ? 'toggle on' : 'toggle'} onClick={() => toggle(row)}><span />{row.is_available ? 'Available' : 'Sold out'}</button><button className="admin-secondary" onClick={() => setEditing(row)}>Edit</button><button className="admin-secondary" onClick={() => remove(row)}>Delete</button></footer></div></article>)}</div>{editing && <Modal title={editing.id ? 'Edit menu item' : 'Add menu item'} close={() => setEditing(null)}><MenuItemForm editing={editing} categories={categories} onSave={save} /></Modal>}</>
}


function offerStatus(offer) { const now = Date.now(); if (!offer.is_active) return 'Off'; if (offer.end_at && new Date(offer.end_at).getTime() <= now) return 'Ended'; if (offer.start_at && new Date(offer.start_at).getTime() > now) return 'Scheduled'; return 'Live' }
function OfferCollage({ images = [], title, className = '' }) { const photos = images.filter(Boolean).slice(0, 4); return <div className={`offer-collage ${className} count-${Math.max(photos.length, 1)}`}>{photos.length ? photos.map((src, index) => <img key={`${src}-${index}`} src={src} alt={`${title} ${index + 1}`} loading="lazy" decoding="async" />) : <span>✦</span>}</div> }
function OfferForm({ editing, menuItems, onSave }) {
  const initialIds = editing?.items?.map((item) => item.menu_item_id || item.id) || []
  const initialImages = editing?.image_urls?.length ? editing.image_urls : editing?.image_url ? [editing.image_url] : []
  const [type, setType] = useState(editing?.type || 'auto'); const [selectedIds, setSelectedIds] = useState(initialIds); const [title, setTitle] = useState(editing?.title || ''); const [titleEdited, setTitleEdited] = useState(Boolean(editing?.id)); const [images, setImages] = useState(() => initialImages.map((url) => ({ id: crypto.randomUUID(), type: 'url', url, preview: url }))); const [imageLink, setImageLink] = useState('')
  const selectedItems = menuItems.filter((item) => selectedIds.includes(item.id)); const generatedTitle = selectedItems.map((item) => item.name).join(' + ')
  const chooseItem = (id) => { const next = selectedIds.includes(id) ? selectedIds.filter((itemId) => itemId !== id) : [...selectedIds, id]; setSelectedIds(next); if (!titleEdited) setTitle(menuItems.filter((item) => next.includes(item.id)).map((item) => item.name).join(' + ')) }
  const addFiles = (event) => { const files = Array.from(event.target.files || []); const invalid = files.find((file) => file.size > 5242880); if (invalid) return notify('Each image must be 5 MB or smaller.', 'error'); setImages((current) => [...current, ...files.map((file) => ({ id: crypto.randomUUID(), type: 'file', file, preview: URL.createObjectURL(file) }))]); event.target.value = '' }
  const addLink = () => { const url = imageLink.trim(); if (!url) return; try { new URL(url) } catch { notify('Enter a complete public image URL.', 'error'); return }; setImages((current) => [...current, { id: crypto.randomUUID(), type: 'url', url, preview: url }]); setImageLink('') }
  const collageImages = selectedItems.flatMap((item) => item.image_urls?.length ? item.image_urls.slice(0, 1) : item.image_url ? [item.image_url] : [])
  return <form className="offer-form" onSubmit={(event) => { event.preventDefault(); if (type === 'auto' && selectedIds.length < 2) return notify('Select at least two menu items for a bundle.', 'error'); onSave(new FormData(event.currentTarget), { type, selectedIds, images }) }}><div className="offer-type-tabs"><button type="button" className={type === 'auto' ? 'active' : ''} onClick={() => setType('auto')}><b>✦ Smart bundle</b><span>Build from menu items</span></button><button type="button" className={type === 'manual' ? 'active' : ''} onClick={() => setType('manual')}><b>▣ Manual offer</b><span>Create your own promotion</span></button></div><input type="hidden" name="type" value={type} />{type === 'auto' && <section className="bundle-builder"><div className="bundle-builder-head"><div><strong>Choose bundle items</strong><small>Select two or more dishes. The title and visual update instantly.</small></div><span>{selectedItems.length} selected</span></div><div className="bundle-item-list">{menuItems.map((item) => <button type="button" className={selectedIds.includes(item.id) ? 'selected' : ''} key={item.id} onClick={() => chooseItem(item.id)}><span>{selectedIds.includes(item.id) ? '✓' : '+'}</span>{item.image_url ? <img src={item.image_url} alt="" /> : <i>🍽</i>}<div><b>{item.name}</b><small>PKR {Number(item.price).toLocaleString()}</small></div></button>)}</div>{selectedItems.length > 0 && <div className="bundle-preview"><OfferCollage images={collageImages} title={title || generatedTitle} /><div><span>AUTOMATIC BUNDLE</span><strong>{generatedTitle || 'Select menu items'}</strong><small>Change the title below if you want a custom name.</small></div></div>}</section>}<div className="offer-form-grid"><Field label="Offer title"><input name="title" required value={title} onChange={(event) => { setTitle(event.target.value); setTitleEdited(true) }} placeholder={type === 'auto' ? 'Generated from selected items' : 'e.g. Weekend special'} /></Field><Field label="Bundle price (PKR)"><input name="price" required type="number" min="0" step="0.01" defaultValue={editing?.price || ''} placeholder="e.g. 200" /></Field><Field label="Starts on"><input name="start_at" type="datetime-local" defaultValue={editing?.start_at ? new Date(editing.start_at).toISOString().slice(0, 16) : ''} /></Field><Field label="Ends on"><input name="end_at" type="datetime-local" defaultValue={editing?.end_at ? new Date(editing.end_at).toISOString().slice(0, 16) : ''} /></Field><Field label="Offer is active"><input name="is_active" type="checkbox" defaultChecked={editing?.is_active ?? true} /></Field><Field label="Description"><textarea name="description" defaultValue={editing?.description || ''} placeholder="Tell guests why this offer is special" /></Field></div>{type === 'manual' && <section className="image-manager"><div className="image-manager-head"><div><strong>Offer images</strong><small>Add dedicated promotion photos from your device or public links.</small></div><span>{images.length} image{images.length === 1 ? '' : 's'}</span></div><div className="image-actions"><label className="image-upload-button">↑ Upload images<input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif" onChange={addFiles} /></label><div className="image-link-add"><input value={imageLink} onChange={(event) => setImageLink(event.target.value)} placeholder="Paste image URL" /><button type="button" onClick={addLink}>Add link</button></div></div>{images.length > 0 && <div className="image-preview-grid">{images.map((image, index) => <article key={image.id}><img src={image.preview} alt="" /><span>{index === 0 ? 'Cover image' : `Image ${index + 1}`}</span><button type="button" onClick={() => setImages((current) => current.filter((item) => item.id !== image.id))} aria-label="Remove image">×</button></article>)}</div>}</section>}<button className="admin-primary">{editing?.id ? 'Save offer changes' : 'Create offer'}</button></form>
}
function Offers({ restaurantId }) {
  const { data: menuItems, loading: menuLoading } = useData('menu_items', restaurantId); const [offers, setOffers] = useState([]); const [loading, setLoading] = useState(true); const [editing, setEditing] = useState(null); const [query, setQuery] = useState(''); const [status, setStatus] = useState('all')
  const reload = async () => { setLoading(true); const { data, error } = await supabase.from('offers').select('*, offer_items(menu_item_id, display_order, menu_items(id, name, image_url, image_urls))').eq('restaurant_id', restaurantId).order('display_order'); if (error) notify(error.message, 'error'); else setOffers((data || []).map((offer) => ({ ...offer, items: (offer.offer_items || []).sort((a, b) => a.display_order - b.display_order).map((link) => ({ ...link.menu_items, menu_item_id: link.menu_item_id })) }))); setLoading(false) }
  useEffect(() => { supabase.from('offers').select('*, offer_items(menu_item_id, display_order, menu_items(id, name, image_url, image_urls))').eq('restaurant_id', restaurantId).order('display_order').then(({ data, error }) => { if (error) notify(error.message, 'error'); else setOffers((data || []).map((offer) => ({ ...offer, items: (offer.offer_items || []).sort((a, b) => a.display_order - b.display_order).map((link) => ({ ...link.menu_items, menu_item_id: link.menu_item_id })) }))); setLoading(false) }) }, [restaurantId])
  const save = async (form, values) => { const files = values.images.filter((image) => image.type === 'file').map((image) => image.file); const links = values.images.filter((image) => image.type === 'url').map((image) => image.url); const uploaded = []; for (const file of files) { const path = `${restaurantId}/${crypto.randomUUID()}-${file.name.replaceAll(' ', '-')}`; const { error } = await supabase.storage.from(menuImageBucket).upload(path, file); if (error) return notify(error.message, 'error'); uploaded.push(supabase.storage.from(menuImageBucket).getPublicUrl(path).data.publicUrl) }; const imageUrls = [...links, ...uploaded]; const startAt = form.get('start_at'); const endAt = form.get('end_at'); if (startAt && endAt && new Date(endAt) <= new Date(startAt)) return notify('The end date must be after the start date.', 'error'); const record = { restaurant_id: restaurantId, type: values.type, title: form.get('title').trim(), description: form.get('description').trim() || null, price: Number(form.get('price')), image_url: values.type === 'manual' ? imageUrls[0] || null : null, image_urls: values.type === 'manual' ? imageUrls : [], start_at: startAt ? new Date(startAt).toISOString() : null, end_at: endAt ? new Date(endAt).toISOString() : null, is_active: form.get('is_active') === 'on', display_order: editing?.display_order ?? offers.length }; const result = editing?.id ? await supabase.from('offers').update(record).eq('id', editing.id).select('id').single() : await supabase.from('offers').insert(record).select('id').single(); if (result.error) return notify(result.error.message, 'error'); const offerId = result.data.id; const { error: clearError } = await supabase.from('offer_items').delete().eq('offer_id', offerId); if (clearError) return notify(clearError.message, 'error'); if (values.type === 'auto' && values.selectedIds.length) { const { error } = await supabase.from('offer_items').insert(values.selectedIds.map((menu_item_id, display_order) => ({ offer_id: offerId, menu_item_id, display_order }))); if (error) return notify(error.message, 'error') }; setEditing(null); reload(); notify(editing?.id ? 'Offer updated.' : 'Offer created.') }
  const toggle = async (offer) => { const { error } = await supabase.from('offers').update({ is_active: !offer.is_active }).eq('id', offer.id); if (error) notify(error.message, 'error'); else { reload(); notify(offer.is_active ? 'Offer turned off.' : 'Offer activated.') } }
  const remove = async (offer) => { if (!confirm(`Delete ${offer.title}?`)) return; const { error } = await supabase.from('offers').delete().eq('id', offer.id); if (error) notify(error.message, 'error'); else { reload(); notify('Offer deleted.') } }
  const visible = offers.filter((offer) => (status === 'all' || offerStatus(offer).toLowerCase() === status) && `${offer.title} ${offer.description || ''}`.toLowerCase().includes(query.toLowerCase()))
  if (loading || menuLoading) return <PageLoader label="Loading offers" />
  return <><Header kicker={`${offers.length} PROMOTIONS`} title="Offer management" action="Create offer" onAction={() => setEditing({})} /><section className="offers-intro"><div><span>SMART PROMOTIONS</span><strong>Bundle menu favourites or launch a custom deal.</strong></div><p>Guests only see active offers. Scheduled and ended offers are clearly labelled.</p></section><div className="qr-toolbar"><label className="toolbar-search">⌕<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search offers" /></label><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All offers</option><option value="live">Live</option><option value="scheduled">Scheduled</option><option value="ended">Ended</option><option value="off">Off</option></select></div>{visible.length ? <div className="offers-admin-grid">{visible.map((offer) => { const images = offer.type === 'auto' ? offer.items.flatMap((item) => item.image_urls?.slice(0, 1) || (item.image_url ? [item.image_url] : [])) : (offer.image_urls?.length ? offer.image_urls : [offer.image_url]); return <article className={`admin-offer-card ${offerStatus(offer).toLowerCase()}`} key={offer.id}><OfferCollage images={images} title={offer.title} /><div className="admin-offer-body"><header><span className={`offer-state ${offerStatus(offer).toLowerCase()}`}>{offerStatus(offer)}</span><span>{offer.type === 'auto' ? 'Smart bundle' : 'Manual offer'}</span></header><h3>{offer.title}</h3><p>{offer.description || 'A special offer for your guests.'}</p><strong>PKR {Number(offer.price).toLocaleString()}</strong><small>{offer.end_at ? `Ends ${new Date(offer.end_at).toLocaleDateString()}` : 'No end date'}</small><footer><button className={offer.is_active ? 'toggle on' : 'toggle'} onClick={() => toggle(offer)}><span />{offer.is_active ? 'On' : 'Off'}</button><button className="admin-secondary" onClick={() => setEditing(offer)}>Edit</button><button className="danger-button" onClick={() => remove(offer)}>Delete</button></footer></div></article> })}</div> : <div className="empty-collection"><span>✦</span><h2>{offers.length ? 'No offers match these filters' : 'Create your first offer'}</h2><p>Bundle popular menu items or make a custom deal for your guests.</p><button className="admin-primary" onClick={() => setEditing({})}>Create offer</button></div>}{editing && <Modal title={editing.id ? 'Edit offer' : 'Create offer'} close={() => setEditing(null)}><OfferForm editing={editing} menuItems={menuItems} onSave={save} /></Modal>}</>
}

function QR({ restaurantId }) {
  const { data, loading, reload } = useData('qr_tokens', restaurantId, 'created_at'); const [table, setTable] = useState(''); const [expiry, setExpiry] = useState(''); const [query, setQuery] = useState(''); const [status, setStatus] = useState('all'); const [createOpen, setCreateOpen] = useState(false)
  const create = async (e) => { e.preventDefault(); const { error } = await supabase.from('qr_tokens').insert({ restaurant_id: restaurantId, table_number: table.trim(), expires_at: expiry ? new Date(expiry).toISOString() : null }); if (error) return notify(`Could not create QR code: ${error.message}`, 'error'); setTable(''); setExpiry(''); setCreateOpen(false); reload(); notify('QR code created successfully.') }
  const now = new Date(); const isExpired = (row) => row.expires_at && new Date(row.expires_at) <= now; const visible = data.filter((row) => (status === 'all' || (status === 'active' ? row.is_active && !isExpired(row) : status === 'inactive' ? !row.is_active : isExpired(row))) && `${row.table_number} ${row.token}`.toLowerCase().includes(query.toLowerCase())); const activeCount = data.filter((row) => row.is_active && !isExpired(row)).length
  if (loading) return <PageLoader label="Loading table QR codes" />
  return <><Header kicker="TABLE ACCESS" title="QR code management" action="Create QR" onAction={() => setCreateOpen(true)} /><section className="qr-overview"><div><strong>{activeCount}</strong><span>Active QR codes</span></div><p>Each table QR is permanent unless you deactivate, delete, regenerate, or give it an expiry time.</p></section><div className="qr-toolbar"><label className="toolbar-search">⌕<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search table name or QR token" /></label><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">All status</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="expired">Expired</option></select></div>{visible.length ? <div className="qr-grid">{visible.map((row) => <QRCard key={row.id} row={row} reload={reload} />)}</div> : <div className="empty-collection"><span>▦</span><h2>{data.length ? 'No QR codes match these filters' : 'Create your first table QR'}</h2><p>{data.length ? 'Try a different table name or status.' : 'Create one QR code per table, then download or print it.'}</p>{!data.length && <button className="admin-primary" onClick={() => setCreateOpen(true)}>Create table QR</button>}</div>}{createOpen && <Modal title="Create table QR" close={() => setCreateOpen(false)}><form className="admin-form-grid" onSubmit={create}><Field label="Table name"><input required value={table} onChange={(e) => setTable(e.target.value)} placeholder="e.g. Table 3" /></Field><Field label="QR expiry (optional)"><input value={expiry} onChange={(e) => setExpiry(e.target.value)} type="datetime-local" /><small>Leave blank to keep this QR permanent.</small></Field><button className="admin-primary">Generate QR code</button></form></Modal>}</>
}
function QRCard({ row, reload }) {
  const [url, setUrl] = useState(''); const link = scanLink(row.token)
  useEffect(() => { QRCode.toDataURL(link, { width: 360, margin: 2 }).then(setUrl) }, [link])
  const update = async (values, successMessage) => { const { error } = await supabase.from('qr_tokens').update(values).eq('id', row.id); if (error) notify(error.message, 'error'); else { reload(); notify(successMessage) } }
  const regenerate = () => { if (confirm(`Generate a new QR link for ${row.table_number}? The old QR will stop working.`)) update({ token: crypto.randomUUID().replaceAll('-', '') }, 'New QR link generated. The old link no longer works.') }
  const remove = () => { if (confirm(`Delete QR code for ${row.table_number}?`)) supabase.from('qr_tokens').delete().eq('id', row.id).then(({ error }) => { if (error) notify(error.message, 'error'); else { reload(); notify('QR code deleted.') } }) }
  const copy = async () => { try { await navigator.clipboard.writeText(link); notify('QR link copied to clipboard.') } catch { notify('Could not copy the QR link.', 'error') } }
  return <article className="qr-card"><header className="qr-card-head"><div><span className={row.is_active ? 'qr-state active' : 'qr-state'}>{row.is_active ? 'Active' : 'Inactive'}</span><h3>{row.table_number}</h3></div><button className="danger-button" onClick={remove}>Delete</button></header><div className="qr-preview">{url ? <img src={url} alt={`QR code for ${row.table_number}`} /> : <span className="qr-preview-loader" />}</div><div className="qr-token"><span>TABLE QR TOKEN</span><code title={row.token}>{row.token}</code></div><div className="qr-primary-action"><button onClick={copy}>⧉ Copy QR link</button></div><div className="qr-secondary-actions"><a href={url} download={`${row.table_number}-qr.png`}>↓ Download</a><button onClick={regenerate}>↻ Regenerate</button><button onClick={() => update({ is_active: !row.is_active }, row.is_active ? 'QR code deactivated.' : 'QR code activated.')}>{row.is_active ? 'Pause access' : 'Activate access'}</button></div></article>
}


function Header({ kicker, title, action, onAction }) { return <div className="admin-heading"><div><span className="admin-kicker">{kicker}</span><h1>{title}</h1></div>{action && <button className="admin-primary" onClick={onAction}>＋ {action}</button>}</div> }

const formatMoney = (amount, currency = 'PKR') => new Intl.NumberFormat(undefined, { style: 'currency', currency, maximumFractionDigits: 0 }).format(Number(amount || 0))
const formatDate = (date) => date ? new Date(date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : 'Not available'
const daysUntil = (date) => date ? Math.max(0, Math.ceil((new Date(date).getTime() - Date.now()) / 86400000)) : null
const relativeTime = (date) => { const minutes = Math.max(0, Math.floor((Date.now() - new Date(date).getTime()) / 60000)); if (minutes < 1) return 'Just now'; if (minutes < 60) return `${minutes}m ago`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours}h ago`; return `${Math.floor(hours / 24)}d ago` }

function SubscriptionBanner({ subscription, openPage }) { const [dismissed, setDismissed] = useState(false); if (!subscription || dismissed) return null; const days = daysUntil(subscription.status === 'trialing' ? subscription.trial_end : subscription.current_period_end); const state = subscription.status === 'trialing' && days !== null && days <= 3 ? 'trial' : subscription.status === 'past_due' ? 'past-due' : subscription.status === 'suspended' || subscription.status === 'canceled' ? 'suspended' : null; if (!state) return null; const text = state === 'trial' ? `Your trial ends in ${days} day${days === 1 ? '' : 's'}. Subscribe now to continue.` : state === 'past-due' ? 'Payment failed. Update your payment method to avoid interruption.' : 'Your subscription requires renewal. Your menu is currently offline.'; return <aside className={`subscription-banner ${state}`}><span>{state === 'trial' ? '!' : '●'}</span><p>{text}</p><button onClick={() => openPage('subscription')}>{state === 'past-due' ? 'Update payment' : state === 'trial' ? 'Subscribe' : 'Renew now'}</button><button className="banner-close" aria-label="Dismiss subscription notice" onClick={() => setDismissed(true)}>×</button></aside> }

function NotificationBell({ notifications, onOpen, openPage }) { const unread = notifications.filter((item) => !item.is_read).length; const [open, setOpen] = useState(false); const latest = notifications.slice(0, 5); const go = () => { setOpen(false); openPage('notifications') }; return <div className="notification-control"><button className={`notification-bell ${unread ? 'has-unread' : ''}`} onClick={() => setOpen(!open)} aria-expanded={open} aria-label={`Notifications${unread ? `, ${unread} unread` : ''}`}>♢{unread > 0 && <b>{unread > 99 ? '99+' : unread}</b>}</button>{open && <section className="notification-popover"><header><strong>Notifications</strong><button onClick={go}>View all</button></header>{latest.length ? latest.map((item) => <button className={!item.is_read ? 'unread' : ''} key={item.id} onClick={() => { onOpen(item); go() }}><b>{item.title}</b><span>{item.message}</span><small>{relativeTime(item.created_at)}</small></button>) : <p>No notifications yet.</p>}</section>}</div> }

function SubscriptionPage({ subscription, openPage }) { if (!subscription) return <><Header kicker="BILLING" title="Subscription" /><div className="empty-collection"><span>▣</span><h2>Subscription details are not ready</h2><p>Your platform administrator has not assigned a subscription yet.</p></div></>; const status = subscription.status; const end = status === 'trialing' ? subscription.trial_end : subscription.current_period_end; const days = daysUntil(end); const title = status === 'trialing' ? 'Free trial active' : status === 'active' ? 'Subscription active' : status === 'past_due' ? 'Payment needs attention' : 'Subscription required'; const action = status === 'past_due' ? 'Update payment method' : status === 'active' ? 'Manage payment method' : status === 'trialing' ? 'Subscribe securely' : 'Renew subscription'; return <><Header kicker="PLAN & BILLING" title="Subscription" /><section className={`subscription-card ${status}`}><div className="subscription-status"><span>{status === 'active' ? '✓' : status === 'trialing' ? '!' : '●'}</span><div><small>{status.replace('_', ' ')}</small><h2>{title}</h2><p>{status === 'suspended' || status === 'canceled' ? 'Renew to restore access to your digital menu.' : `Your ${subscription.plan?.name || 'current'} plan is managed securely by Plato Table.`}</p></div></div><div className="subscription-facts"><div><span>Plan</span><strong>{subscription.plan?.name || 'Current plan'}</strong></div><div><span>Price</span><strong>{formatMoney(subscription.amount, subscription.currency)} / period</strong></div><div><span>{status === 'trialing' ? 'Trial ends' : 'Period ends'}</span><strong>{formatDate(end)}</strong><small>{days === null ? '' : `${days} day${days === 1 ? '' : 's'} remaining`}</small></div><div><span>Billing period</span><strong>{formatDate(subscription.current_period_start)} — {formatDate(subscription.current_period_end)}</strong></div></div>{subscription.cancel_at_period_end && <p className="cancel-note">Cancellation is scheduled for the end of this billing period.</p>}<footer><button className="admin-primary" onClick={() => openPage('payment')}>{action}</button><button className="admin-secondary" onClick={() => openPage('billing')}>View billing history</button></footer></section></> }

function BillingHistory({ restaurantId, openPage }) { const { data, loading, error } = useData('payment_transactions', restaurantId, 'created_at'); if (loading) return <PageLoader label="Loading billing history" />; const paid = data.filter((item) => item.status === 'succeeded').reduce((total, item) => total + Number(item.amount || 0), 0); const exportCsv = () => { const rows = [['Date', 'Amount', 'Currency', 'Status'], ...data.map((item) => [new Date(item.created_at).toISOString(), item.amount, item.currency, item.status])]; const blob = new Blob([rows.map((row) => row.join(',')).join('\n')], { type: 'text/csv' }); const href = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = href; anchor.download = 'billing-history.csv'; anchor.click(); URL.revokeObjectURL(href) }; return <><Header kicker="PLAN & BILLING" title="Billing history" action="Export CSV" onAction={exportCsv} />{error && <div className="login-error">{error}</div>}<section className="billing-summary"><span>Total paid</span><strong>{formatMoney(paid, data[0]?.currency || 'PKR')}</strong><button className="admin-secondary" onClick={() => openPage('subscription')}>Back to subscription</button></section><div className="billing-table">{data.length ? data.map((item) => <article key={item.id}><time>{formatDate(item.created_at)}</time><strong>{formatMoney(item.amount, item.currency)}</strong><span className={`transaction-status ${item.status}`}>{item.status}</span>{item.invoice_url ? <a href={item.invoice_url} target="_blank" rel="noreferrer">Invoice ↗</a> : <span className="no-invoice">Invoice unavailable</span>}</article>) : <div className="empty-collection"><span>▤</span><h2>No transactions yet</h2><p>Completed payments will appear here.</p></div>}</div></> }

function PaymentMethod({ subscription, openPage }) { return <><Header kicker="SECURE BILLING" title="Payment method" /><section className="payment-method-card"><span className="settings-icon">▣</span><h2>Manage payment securely</h2><p>Payment details are managed in the secure billing portal. This app never stores or displays full card numbers, CVVs, or cardholder details.</p>{subscription?.provider === 'stripe' ? <p className="payment-note">The billing portal link must be created by a trusted server using your Stripe secret key. No portal endpoint is configured for this deployment.</p> : <p className="payment-note">Your subscription is managed by the platform team. Contact support to update your payment method or renew.</p>}<div><button className="admin-secondary" onClick={() => openPage('billing')}>View invoices</button><button className="admin-primary" onClick={() => window.location.href = 'mailto:support@platotable.com?subject=Billing%20support'}>Contact billing support</button></div></section></> }

function Notifications({ notifications, refresh }) { const [filter, setFilter] = useState('all'); const [selected, setSelected] = useState(null); const mark = async (id, read = true) => { const { error } = await supabase.rpc('mark_restaurant_notification_read', { p_notification_id: id, p_is_read: read }); if (error) notify(error.message, 'error'); else refresh() }; const visible = notifications.filter((item) => filter === 'all' || (filter === 'unread' ? !item.is_read : item.is_read)); return <><Header kicker="PLATFORM UPDATES" title="Notifications" action="Mark all as read" onAction={() => Promise.all(notifications.filter((item) => !item.is_read).map((item) => mark(item.id))).then(refresh)} /><div className="notification-filters"><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>All</button><button className={filter === 'unread' ? 'active' : ''} onClick={() => setFilter('unread')}>Unread</button><button className={filter === 'read' ? 'active' : ''} onClick={() => setFilter('read')}>Read</button></div><section className="notification-list">{visible.length ? visible.map((item) => <article className={`${item.background_color} ${item.is_read ? '' : 'unread'}`} key={item.id} onClick={() => setSelected(item)}><span>{item.type === 'critical' ? '●' : item.type === 'success' ? '✓' : '!'}</span><div><h2>{item.title}</h2><p>{item.message}</p><small>{relativeTime(item.created_at)}</small></div>{!item.is_read && <button className="admin-secondary" onClick={(event) => { event.stopPropagation(); mark(item.id) }}>Mark read</button>}</article>) : <div className="empty-collection"><span>♢</span><h2>No notifications</h2><p>You're all caught up.</p></div>}</section>{selected && <Modal title={selected.title} close={() => setSelected(null)}><div className="notification-detail"><p>{selected.message}</p><small>{formatDate(selected.created_at)}</small>{!selected.is_read && <button className="admin-primary" onClick={() => { mark(selected.id); setSelected(null) }}>Mark as read</button>}</div></Modal>}</> }

function Usage({ restaurantId }) { const { data: scans, loading: scansLoading } = useData('scan_logs', restaurantId, 'scanned_at'); const { data: items, loading: itemsLoading } = useData('menu_items', restaurantId); const { data: categories, loading: categoriesLoading } = useData('categories', restaurantId); const [period, setPeriod] = useState('month'); if (scansLoading || itemsLoading || categoriesLoading) return <PageLoader label="Loading usage statistics" />; const since = new Date(); since.setDate(since.getDate() - (period === 'week' ? 7 : period === 'month' ? 30 : 90)); const rows = scans.filter((scan) => new Date(scan.scanned_at) >= since); const days = [...Array(period === 'week' ? 7 : period === 'month' ? 30 : 90)].map((_, i) => { const day = new Date(since); day.setDate(day.getDate() + i); return { label: day.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }), count: rows.filter((scan) => new Date(scan.scanned_at).toDateString() === day.toDateString()).length } }); const peak = Array.from({ length: 24 }, (_, hour) => rows.filter((scan) => new Date(scan.scanned_at).getHours() === hour).length); const max = Math.max(...days.map((day) => day.count), 1); return <><Header kicker="RESTAURANT ACTIVITY" title="Usage statistics" /><div className="usage-period"><label>Period <select value={period} onChange={(event) => setPeriod(event.target.value)}><option value="week">Last 7 days</option><option value="month">Last 30 days</option><option value="quarter">Last 90 days</option></select></label></div><div className="stats-grid usage-stats"><article className="stat-card"><span>QR scans</span><strong>{rows.length}</strong><small>Selected period</small></article><article className="stat-card"><span>Menu items</span><strong>{items.length}</strong><small>Currently configured</small></article><article className="stat-card"><span>Categories</span><strong>{categories.length}</strong><small>Currently configured</small></article></div><div className="usage-grid"><section className="admin-card chart-card"><h2>Scans over time</h2><div className="bar-chart">{days.map((day) => <div key={day.label} title={`${day.label}: ${day.count} scans`}><i style={{ height: `${Math.max(4, (day.count / max) * 100)}%` }} /><small>{day.label}</small></div>)}</div></section><section className="admin-card chart-card"><h2>Peak hours</h2><div className="peak-list">{peak.map((count, hour) => <div key={hour}><span>{String(hour).padStart(2, '0')}:00</span><i><b style={{ width: `${(count / Math.max(...peak, 1)) * 100}%` }} /></i><strong>{count}</strong></div>)}</div></section></div><section className="admin-card usage-note"><h2>Item views</h2><p>Item-view events are not collected by the current schema, so top viewed items cannot be shown yet. Scan, menu, and category metrics above use existing restaurant data only.</p></section></> }
function Modal({ title, close, children }) { return <div className="admin-modal-backdrop"><section className="admin-modal"><header><h2>{title}</h2><button onClick={close}>×</button></header>{children}</section></div> }

function Shell({ theme, toggleTheme }) {
  const navigate = useNavigate(); const location = useLocation(); const page = location.pathname.split('/').filter(Boolean).slice(2).join('/') || 'dashboard'; const [restaurant, setRestaurant] = useState(null); const [subscription, setSubscription] = useState(null); const [notifications, setNotifications] = useState([]); const [setupError, setSetupError] = useState(''); const openPage = (id) => navigate(id === 'dashboard' ? `/admin/${restaurantSlug}` : `/admin/${restaurantSlug}/${id}`); const loadAccountData = async (restaurantId) => { const [subscriptionResult, notificationResult] = await Promise.all([supabase.from('subscriptions').select('*, plan:subscription_plans(name, duration_days)').eq('restaurant_id', restaurantId).maybeSingle(), supabase.from('system_notifications').select('*').or(`restaurant_id.eq.${restaurantId},restaurant_id.is.null`).or('scheduled_at.is.null,scheduled_at.lte.now()').or('expires_at.is.null,expires_at.gt.now()').order('created_at', { ascending: false })]); if (subscriptionResult.error) notify(subscriptionResult.error.message, 'error'); else setSubscription(subscriptionResult.data); if (notificationResult.error) notify(notificationResult.error.message, 'error'); else setNotifications(notificationResult.data || []) }
  useEffect(() => {
    let mounted = true
    const loadRestaurant = async () => {
      const { data: { user }, error: userError } = await supabase.auth.getUser()
      if (userError || !user) { await supabase.auth.signOut(); navigate(`/admin/${restaurantSlug}/login`, { replace: true }); return }
      const { data, error } = await supabase.from('restaurant_admins').select('restaurant_id, restaurants!inner(name, subdomain, owner_email, phone, contact_email)').eq('user_id', user.id).eq('is_active', true).eq('restaurants.subdomain', restaurantSlug).maybeSingle()
      if (!mounted) return
      if (error) { setSetupError(error.message); return }
      if (data) { const restaurantRecord = { id: data.restaurant_id, name: data.restaurants?.name || 'Restaurant', email: data.restaurants?.owner_email || '', phone: data.restaurants?.phone || '', contactEmail: data.restaurants?.contact_email || '' }; setRestaurant(restaurantRecord); loadAccountData(restaurantRecord.id); return }
      // No bootstrap fallback: the live database has no bootstrap helper, and an
      // account that does not manage this slug must never be silently attached to
      // a different restaurant.
      setSetupError(`This account does not manage ${restaurantSlug}. Sign in to the correct restaurant workspace.`)
    }
    loadRestaurant(); return () => { mounted = false }
  }, [navigate])
  useEffect(() => { if (!restaurant) return undefined; const timer = window.setInterval(() => loadAccountData(restaurant.id), 60000); return () => window.clearInterval(timer) }, [restaurant])
  useEffect(() => { const locked = subscription?.status === 'suspended' || subscription?.status === 'canceled'; if (restaurant && locked && !subscriptionPages.includes(page)) navigate(`/admin/${restaurantSlug}/subscription`, { replace: true }) }, [restaurant, subscription, page, navigate])
  if (setupError) return <main className="scan-error"><BrandMark size={42} /><h1>Admin setup incomplete</h1><p>{setupError}</p><button className="admin-primary" onClick={() => supabase.auth.signOut().then(() => navigate(`/admin/${restaurantSlug}/login`))}>Log out</button></main>
  if (!restaurant) return <main className="scan-error"><span className="scan-spinner" /><p>Loading your restaurant…</p></main>
  const locked = subscription?.status === 'suspended' || subscription?.status === 'canceled'; const activePage = locked && !subscriptionPages.includes(page) ? 'subscription' : page; const views = { dashboard: <Dashboard restaurantId={restaurant.id} openPage={openPage} />, menu: <Menu restaurantId={restaurant.id} />, offers: <Offers restaurantId={restaurant.id} />, categories: <Categories restaurantId={restaurant.id} />, qr: <QR restaurantId={restaurant.id} />, subscription: <SubscriptionPage subscription={subscription} openPage={openPage} />, billing: <BillingHistory restaurantId={restaurant.id} openPage={openPage} />, payment: <PaymentMethod subscription={subscription} openPage={openPage} />, notifications: <Notifications notifications={notifications} refresh={() => loadAccountData(restaurant.id)} />, usage: <Usage restaurantId={restaurant.id} />, settings: <Settings restaurant={restaurant} openPage={openPage} /> }
  return <main className="admin-shell"><aside className="admin-sidebar"><Link className="admin-brand" to={`/admin/${restaurantSlug}`}><BrandMark size={38} /><div><strong>Plato Table</strong><small>{restaurant.name}</small></div></Link><nav>{nav.map(([id, icon, label]) => <button disabled={locked && !subscriptionPages.includes(id)} className={id === activePage ? 'active' : ''} key={id} onClick={() => openPage(id)}><span>{icon}</span>{label}</button>)}</nav><div className="sidebar-footer"><div className="restaurant-chip"><span>{restaurant.name.slice(0, 2)}</span><div><strong>{restaurant.name}</strong><small>Administrator</small></div></div><button onClick={() => supabase.auth.signOut().then(() => navigate(`/admin/${restaurantSlug}/login`))}>↪ Log out</button></div></aside><section className="admin-workspace"><header className="admin-topbar"><div className="mobile-admin-brand"><BrandMark size={28} /><strong>Plato Table</strong></div><span className="topbar-page">{nav.find(([id]) => id === activePage)?.[2] || 'Billing'}</span><div className="topbar-actions"><button className="admin-theme-toggle" onClick={toggleTheme} aria-label={theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme'} aria-pressed={theme === 'dark'} title={theme === 'dark' ? 'Switch to light theme' : 'Switch to dark theme'}>{theme === 'dark' ? '\u2600' : '\u263e'}</button><NotificationBell notifications={notifications} onOpen={(item) => !item.is_read && supabase.rpc('mark_restaurant_notification_read', { p_notification_id: item.id, p_is_read: true }).then(() => loadAccountData(restaurant.id))} openPage={openPage} /><Link to={`/${restaurantSlug}`}>Open customer menu ↗</Link></div></header><div className="admin-content"><SubscriptionBanner subscription={subscription} openPage={openPage} />{locked && activePage === 'subscription' && <section className="payment-wall"><span>●</span><h2>Subscription required</h2><p>Your subscription has ended. Renew to restore your digital menu and admin tools.</p></section>}{views[activePage] || views.dashboard}</div><Feedback /></section></main>
}

function Settings({ restaurant, openPage }) {
  const [name, setName] = useState(restaurant.name); const [phone, setPhone] = useState(restaurant.phone); const [contactEmail, setContactEmail] = useState(restaurant.contactEmail); const [billingEmail, setBillingEmail] = useState(restaurant.email); const [taxId, setTaxId] = useState(''); const [billingAddress, setBillingAddress] = useState(''); const [password, setPassword] = useState(''); const [confirmPassword, setConfirmPassword] = useState('')
  useEffect(() => { supabase.from('restaurants').select('billing_email, tax_id, billing_address').eq('id', restaurant.id).maybeSingle().then(({ data, error }) => { if (!error && data) { setBillingEmail(data.billing_email || restaurant.email); setTaxId(data.tax_id || ''); setBillingAddress(data.billing_address || '') } }) }, [restaurant.id, restaurant.email])
  const saveProfile = async () => { const { error } = await supabase.from('restaurants').update({ name: name.trim(), phone: phone.trim() || null, contact_email: contactEmail.trim() || null }).eq('id', restaurant.id); if (error) notify(error.message, 'error'); else notify('Restaurant contact details saved.') }
  const saveBilling = async () => { const { error } = await supabase.from('restaurants').update({ billing_email: billingEmail.trim() || null, tax_id: taxId.trim() || null, billing_address: billingAddress.trim() || null }).eq('id', restaurant.id); if (error) notify(error.message, 'error'); else notify('Billing details saved.') }
  const changePassword = async (e) => { e.preventDefault(); if (password.length < 6) return notify('Use a password with at least 6 characters.', 'error'); if (password !== confirmPassword) return notify('Passwords do not match.', 'error'); const { error } = await supabase.auth.updateUser({ password }); if (error) notify(error.message, 'error'); else { setPassword(''); setConfirmPassword(''); notify('Password updated successfully.') } }
  return <><Header kicker="RESTAURANT PROFILE" title="Settings" /><section className="settings-hero"><span>PALATOTABLE · {restaurant.name}</span><p>Customer contact details appear in the menu settings screen.</p></section><div className="settings-grid"><article className="admin-card settings-form"><header><span className="settings-icon">⌁</span><div><h2>Customer contact</h2><p>Shown to guests when they need help.</p></div></header><Field label="Restaurant name"><input value={name} onChange={(e) => setName(e.target.value)} /></Field><Field label="Phone number"><input type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Add a phone number" /></Field><Field label="Customer contact email"><input type="email" value={contactEmail} onChange={(e) => setContactEmail(e.target.value)} placeholder="Add a customer contact email" /></Field><button className="admin-primary" onClick={saveProfile}>Save restaurant details</button></article><article className="admin-card settings-form"><header><span className="settings-icon">▣</span><div><h2>Billing</h2><p>Used for subscription invoices and billing support.</p></div></header><Field label="Billing email"><input type="email" value={billingEmail} onChange={(e) => setBillingEmail(e.target.value)} placeholder="billing@example.com" /></Field><Field label="Tax ID (optional)"><input value={taxId} onChange={(e) => setTaxId(e.target.value)} placeholder="Add tax ID" /></Field><Field label="Billing address"><textarea value={billingAddress} onChange={(e) => setBillingAddress(e.target.value)} placeholder="Street, city, postal code" /></Field><button className="admin-primary" onClick={saveBilling}>Save billing details</button><div className="settings-links"><button className="admin-secondary" onClick={() => openPage('payment')}>Update payment method</button><button className="admin-secondary" onClick={() => openPage('billing')}>View invoices</button></div></article><form className="admin-card settings-form" onSubmit={changePassword}><header><span className="settings-icon">⌑</span><div><h2>Account security</h2><p>Keep staff access private and secure.</p></div></header><Field label="Admin email"><input value={restaurant.email} disabled readOnly /></Field><Field label="New password"><input required type="password" autoComplete="new-password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field><Field label="Confirm new password"><input required type="password" autoComplete="new-password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} /></Field><button className="admin-primary">Update password</button><aside className="security-note">After three failed password attempts, this browser is locked from signing in for one hour.</aside></form></div></>
}
export default function AdminApp({ login = false }) {
  // The wrapper carries the theme for both surfaces, so the sign-in screen and
  // the workspace never disagree about which appearance is active.
  const { theme, toggle } = useTheme('palatotable-admin-theme')
  return <div className="admin-theme-root" data-theme={theme}>{login ? <Login /> : <Shell theme={theme} toggleTheme={toggle} />}</div>
}
